from pathlib import Path
import json
OPS=json.loads('{"assets/gas.css":[[0,0,0,"","/* Ashraellen — GAS book-detail page type\\n   One shared stylesheet for every language version at /xx/books/monolith/gas/.\\n   No dependency on books.css, no page-local <style>, no inline style=\\"\\" attributes.\\n   GAS is its own page type, structurally distinct from BETON/SLUDGE: it keeps its\\n   own gas-prefixed / registry-prefixed class system and its own Registry of\\n   Meanings section — these are not aligned to BETON/SLUDGE naming for the sake of sameness.\\n   Typography for narrative content follows tokens.css roles (body / lead / accent /\\n   kicker / registry).\\n*/\\n@import url(\\"tokens.css\\");\\n\\n:root{--warm:rgba(210,150,80,.07)}\\n\\n*{box-sizing:border-box}\\nhtml,body{height:100%}\\nbody{margin:0;font-family:ui-sans-serif,system-ui,-apple-system,\\"Segoe UI\\",Roboto,Arial,\\"Noto Sans\\",\\"Liberation Sans\\",sans-serif;background:var(--bg);color:var(--fg)}\\na{color:var(--fg);text-decoration:none}\\na:hover{text-decoration:underline}\\n\\n.wrap{min-height:100vh}\\n.page{position:relative;min-height:100vh;overflow:hidden;display:flex;flex-direction:column}\\n.page::before{content:\\"\\";position:absolute;inset:0;background:url(\\"backgrounds/monolith-bg.webp\\") center/cover no-repeat;filter:brightness(.48) contrast(1.08) saturate(.72) blur(1.5px);transform:scale(1.02);z-index:0;will-change:transform;animation:gasDrift 80s ease-in-out infinite alternate}\\n.page::after{content:\\"\\";position:absolute;inset:0;background:linear-gradient(90deg,rgba(11,11,13,.92) 0%,rgba(11,11,13,.74) 30%,rgba(11,11,13,.46) 58%,rgba(11,11,13,.18) 82%,rgba(11,11,13,.06) 100%),radial-gradient(70% 80% at 62% 45%,var(--warm) 0%,rgba(210,150,80,0) 70%);z-index:1}\\n@keyframes gasDrift{0%{transform:scale(1.02) translate3d(0,0,0)}100%{transform:scale(1.042) translate3d(-.4%,-.25%,0)}}\\n@media(prefers-reduced-motion:reduce){.page::before{animation:none}}\\n\\n.site-header{position:relative;z-index:2;padding:22px 44px 0;text-align:right}\\n.site-header .brand{margin:0 0 6px;letter-spacing:.22em;text-transform:uppercase;font-size:14px;font-weight:600;opacity:.92}\\n.site-header .menu{font-size:13px;color:var(--muted)}\\n.site-header .menu a{color:var(--muted);margin:0 10px}\\n.site-header .menu a:hover{color:var(--fg);text-decoration:none}\\n\\n.main{position:relative;z-index:2;flex:1;display:flex;align-items:center;justify-content:center}\\n.container{width:min(100%,980px);max-width:980px;margin:0 auto;padding:28px 44px 56px;text-shadow:0 2px 8px rgba(0,0,0,.84),0 0 22px rgba(0,0,0,.46)}\\n\\n.h1{margin:0 0 10px;font-size:28px;font-weight:800;letter-spacing:.02em}\\n.lead{margin:0 0 16px;font-size:var(--fs-lead);line-height:var(--lh-lead);color:var(--muted);max-width:78ch}\\n\\n/* Case-file hero: cover + protocol number + opening quote */\\n.book-hero{display:grid;grid-template-columns:220px 1fr;gap:22px;align-items:start}\\n.book-cover{border-radius:16px;overflow:hidden;border:1px solid rgba(242,242,244,.14);background:rgba(0,0,0,.18)}\\n.book-cover img{display:block;width:100%;height:auto}\\n\\n.protocol{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;color:var(--muted);font-size:var(--fs-kicker);line-height:var(--lh-kicker);letter-spacing:.04em}\\n\\n.quote-line{font-family:Georgia,\\"Times New Roman\\",serif;font-size:var(--fs-accent);line-height:var(--lh-accent);color:var(--fg);margin:0 0 12px}\\n\\n/* Running descriptive copy */\\n.gas-copy{font-size:var(--fs-body);line-height:var(--lh-body);color:var(--muted);max-width:82ch}\\n.gas-copy p{margin:0 0 12px}\\n.gas-copy p:last-child{margin-bottom:0}\\n\\n.cta-row{display:flex;gap:12px;flex-wrap:wrap;margin-top:14px}\\n.cta-row .btn{font-size:12px;padding:10px 14px;font-weight:700}\\n.btn{display:inline-flex;align-items:center;justify-content:center;padding:12px 18px;border-radius:14px;border:1px solid rgba(242,242,244,.18);background:rgba(0,0,0,.22);backdrop-filter:blur(3px);font-weight:800;text-decoration:none;cursor:pointer;user-select:none;transition:transform 140ms ease,background 140ms ease,border-color 140ms ease,opacity 140ms ease;opacity:.95;color:var(--fg)!important;appearance:none;-webkit-appearance:none;outline:none}\\n.btn:hover{background:rgba(255,255,255,.08);border-color:rgba(242,242,244,.34);transform:translateY(-1px);opacity:1;text-decoration:none;color:var(--fg)!important}\\n.btn:active{transform:translateY(0) scale(.99)}\\n.btn:focus-visible{box-shadow:0 0 0 2px rgba(242,242,244,.18),0 0 0 6px rgba(242,242,244,.08)}\\n.btn.secondary{font-weight:700;border-color:rgba(242,242,244,.14);background:rgba(0,0,0,.16);opacity:.95;color:var(--fg)!important}\\n\\n/* Excerpt toggles — GAS has three independent details/summary blocks\\n   (full protocol, selected fragment, apocrypha), same open/closed label\\n   swap behavior in all 10 languages */\\n.gas-fragment{margin-top:12px;border:1px solid rgba(242,242,244,.12);border-radius:14px;padding:12px;background:rgba(0,0,0,.20)}\\n.gas-fragment summary{cursor:pointer;color:var(--fg);font-weight:700}\\n.gas-fragment summary .when-open{display:none}\\n.gas-fragment[open] summary .when-closed{display:none}\\n.gas-fragment[open] summary .when-open{display:inline}\\n.gas-fragment-body{margin-top:12px}\\n.gas-fragment-body p{max-width:82ch}\\n\\n/* List sections (About, Themes, Where to read, etc.) */\\n.list{margin-top:14px;border:1px solid rgba(242,242,244,.07);border-radius:18px;background:rgba(0,0,0,.18);backdrop-filter:blur(4px);overflow:hidden;box-shadow:0 12px 34px rgba(0,0,0,.18)}\\n.list-header{padding:14px 16px;border-bottom:1px solid rgba(242,242,244,.055);display:flex;align-items:baseline;justify-content:space-between;gap:12px}\\n.list-header h2{margin:0;font-size:16px;font-weight:700}\\n.list-header .note{margin:0}\\n.note{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;color:var(--muted);font-size:var(--fs-kicker);line-height:var(--lh-kicker)}\\n\\n.gas-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:14px}\\n.gas-card,.gas-link-box{border:1px solid rgba(242,242,244,.12);border-radius:14px;padding:14px;background:rgba(0,0,0,.20)}\\n.gas-card h3{margin:0 0 7px;color:var(--fg);font-size:15px;line-height:1.25}\\n.gas-card p{margin:0 0 6px;color:var(--muted);font-size:var(--fs-body);line-height:var(--lh-body)}\\n.gas-card p:last-child{margin-bottom:0}\\n.gas-link-box .cta-row{margin:0}\\n\\n/* Registry of Meanings — GAS-specific structural role, not shared with any\\n   other page type. Dense repeating monospace index: 15 chapter cards,\\n   45 section entries. Reuses the .gas-grid three-column layout mechanics\\n   but its own typography via the --fs-registry / --lh-registry tokens. */\\n.registry-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}\\n.registry-card p{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:var(--fs-registry);line-height:var(--lh-registry)}\\n\\n.seal{display:flex;align-items:center;gap:10px;margin-top:24px;color:var(--muted);font-size:var(--fs-kicker)}\\n.seal img{height:22px;width:auto;opacity:.75}\\n\\n@media(max-width:900px){\\n  .site-header{padding:16px 22px 0}\\n  .main{align-items:flex-start;justify-content:center}\\n  .container{width:100%;padding:22px 22px 44px}\\n  .gas-grid,.registry-grid{grid-template-columns:1fr}\\n}\\n@media(max-width:700px){.book-hero{grid-template-columns:1fr}.book-cover{max-width:260px}}\\n"]]}')
for path, ops in OPS.items():
    p=Path(path)
    if not p.exists():
        assert all(o[0]==0 and o[1]==0 and o[2]==0 and o[3]=="" for o in ops), path
        p.parent.mkdir(parents=True,exist_ok=True)
        p.write_text("".join(o[4] for o in ops))
        continue
    text=p.read_text(); original=text
    starts=[0]
    for i,ch in enumerate(original):
        if ch=="\n": starts.append(i+1)
    edits=[]
    for line_start,rel_s,rel_e,old,new in ops:
        base=starts[line_start-1] if line_start>0 else 0
        s=base+rel_s; e=base+rel_e
        assert original[s:e]==old,(path,line_start,rel_s,repr(old[:160]),repr(original[s:e][:160]))
        edits.append((s,e,new))
    for s,e,new in sorted(edits,key=lambda x:x[0],reverse=True): text=text[:s]+new+text[e:]
    p.write_text(text)
